cypress_script:
describe('Horizontal Slider Control', () => {
  it('should adjust the slider value on interaction', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]').invoke('val', 50).trigger('input');
    cy.get('span#range').should('have.text', '50');
  });

  it('should not change the URL when the slider is adjusted', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]').invoke('val', 75).trigger('input');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/horizontal_slider');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Horizontal Slider Control', () => {
  test('should adjust the slider value on interaction', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    await page.locator('input[type="range"]').fill('50');
    await page.locator('input[type="range"]').dispatchEvent('input');
    const rangeValue = await page.locator('span#range').innerText();
    expect(rangeValue).toBe('50');
  });

  test('should not change the URL when the slider is adjusted', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    const initialUrl = page.url();
    await page.locator('input[type="range"]').fill('75');
    await page.locator('input[type="range"]').dispatchEvent('input');
    expect(page.url()).toBe(initialUrl);
  });
});
